"""Ablate old eight-clause support projection from median-range projection."""
from pathlib import Path
import json,hashlib
from n100_arc_ranked_projection import ROOT,load,need,labels,setup,build,intersect,independent_tile,coupled,independent,width

def main():
 oldsource='verify/out/n100-arc-bounded-learning.json';newsource='verify/out/n100-arc-ranked-projection.json';old=load(oldsource);new=load(newsource);p=old['placement'];node=old['source_node'];base=next(c['result']['boxes'] for c in load('verify/out/n100-arc-center-projection.json')['cases'] if c['placement']==p and c['source_node']==node);core=load('verify/out/n100-cubic-core-roundtrip.json')['core'];prior=next(c['boxes'] for c in load('verify/out/n100-axis-coupled-boxes.json')['retained'] if c['placement']==p);_,E,q=setup(core,p,prior);_,IE,Iq=independent.setup(core,p,prior);_,adj,_=build(core);pairs=sorted({tuple(sorted((i,j))) for i,row in enumerate(adj) for j in row if i!=j});signs={(1,1):0,(-1,1):1,(-1,-1):2,(1,-1):3};B=[b[:] for b in base]
 for raw,bits in old['final_supported_domains'].items():
  v=int(raw);parts=[intersect(base[v],independent_tile(j,256,signs[q[v-100]])) for j in labels(bits)];parts=[b for b in parts if b is not None];need(parts,'old projection nonempty');B[v]=[min(b[0] for b in parts),max(b[1] for b in parts),min(b[2] for b in parts),max(b[3] for b in parts)]
 a=coupled(B,E,q,pairs,limit=160);b=coupled(B,IE,Iq,pairs,alt=True,limit=160);need(a==b and not a['excluded'] and a['fixed'],'old projection fixed replay');need(not new['result']['excluded'] and new['result']['fixed'],'new fixed result');N=new['result']['boxes'];need(all(a['boxes'][i][0]<=v[0]<=v[1]<=a['boxes'][i][1] and a['boxes'][i][2]<=v[2]<=v[3]<=a['boxes'][i][3] for i,v in enumerate(N)),'new fixed boxes nested in old');summary={'parent_width':width(base),'old_eight_clause_projected_width':width(B),'old_eight_clause_fixed_width':width(a['boxes']),'new_nine_clause_fixed_width':width(N),'additional_width_removed_by_median_range':width(a['boxes'])-width(N)};out=ROOT/'verify/out/n100-arc-ranked-ablation.json';need(not out.exists(),'overwrite');paths=[oldsource,newsource,'verify/out/n100-arc-center-projection.json','verify/out/n100-cubic-core-roundtrip.json','verify/out/n100-axis-coupled-boxes.json','verify/n100_arc_ranked_projection.py'];out.write_text(json.dumps({'schema':'n100-arc-ranked-ablation/v1','verified_integer_ablation':True,'old_eight_clause_alternate_replay_equal':True,'new_boxes_nested_in_old_fixed_boxes':True,'summary':summary,'old_eight_clause_result':a,'scope':'same parent and propagation schedule; isolates new median range from earlier support projection, does not prove feasibility','machine_verified_geometry':False,'global_optimality':False,'bindings':{s:hashlib.sha256((ROOT/s).read_bytes()).hexdigest() for s in paths},'script_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest()},indent=2)+'\n',encoding='utf-8');print('PASS median ablation',summary)
if __name__=='__main__':main()
